UPDATE task_run SET status='CANCEL_REQUESTED',reason_code='USER_CANCELLED',dispatch_closed_at=COALESCE(dispatch_closed_at,#{now}),
  revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND run_id=#{runId} AND revision=#{expectedRevision}
  AND status=#{previousStatus} AND status IN ('QUEUED','RUNNING','WAITING_INPUT')
